// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 100 ether);
        Actor actor = new Actor();
        vm.deal(address(actor), amount);
        actor.doDeposit(c, amount);

        actor.doWithdraw(c, amount);

        // Rule: after a successful withdraw of `amount`, the actor's recorded
        // balance is zero AND the contract's Ether balance dropped by `amount`.
        assertTrue(
            c.balances(address(actor)) == 0 && address(c).balance == 0,
            "withdraw must decrement balance and contract ether"
        );
    }
}

contract Actor {
    function doDeposit(C c, uint256 amount) external payable {
        c.deposit{value: amount}();
    }
    function doWithdraw(C c, uint256 amount) external {
        c.withdraw(amount);
    }
    receive() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 secondAmount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        uint256 dep = bound(depositAmount, 1, 100 ether);
        uint256 second = bound(secondAmount, 1, 100 ether);

        vm.deal(actor, dep);
        vm.prank(actor);
        c.deposit{value: dep}();

        // actor withdraws their entire recorded balance; P reduces balances[actor] to 0
        vm.prank(actor);
        c.withdraw(dep);

        // any further positive withdrawal must revert in P (require amount <= balance)
        bool ok;
        vm.prank(actor);
        try c.withdraw(second) { ok = true; } catch { ok = false; }

        assertTrue(!ok);
    }
}

