    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 init, uint256 amount) public {
        // keep parameters in the admissible domain (wide)
        init = bound(init, 2, 1e30);
        amount = bound(amount, 1, init / 2);

        // adversarial re-entrant counterparty
        Attacker a = new Attacker(c);
        vm.deal(address(a), init);

        // attacker deposits `init`, then withdraws `amount`;
        // during the transfer out, its receive() re-enters c and inspects
        // whether the recorded balance has already been decremented.
        bool ok = a.run(amount);

        // General rule: the full deposit+withdraw cycle with a re-entrant
        // counterparty completes and leaves exactly init - amount in c.
        // Reference C: mid-transfer balance is init - amount (nonzero),
        // re-entrant observer lets it finish -> ok, address(c).balance == init - amount.
        // Mutant: mid-transfer balance is already 0 -> observer reverts ->
        // the whole withdraw reverts -> ok == false and address(c).balance == init.
        assertTrue(ok && address(c).balance == init - amount);
    }
}

contract Attacker {
    C c;
    constructor(C c_) { c = c_; }

    function run(uint256 amount) external returns (bool ok) {
        c.deposit{value: address(this).balance}();
        try c.withdraw(amount) { ok = true; } catch { ok = false; }
    }

    receive() external payable {
        // re-entrant read of our own recorded balance (fits in the transfer stipend:
        // slot is already warm in this transaction)
        (bool okr, bytes memory ret) =
            address(c).staticcall(abi.encodeWithSignature("balances(address)", address(this)));
        require(okr, "read failed");
        // If the balance was already decremented before the transfer (the bug),
        // it reads 0 mid-withdrawal: abort.
        if (abi.decode(ret, (uint256)) == 0) revert();
    }
}

