pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C();
        attacker = new Attacker();
    }

    function testFuzz_property(uint256 d, uint256 a, uint256 a2) public {
        d = bound(d, 1, 1e30);
        vm.assume(a >= 1 && a <= d);
        vm.assume(a2 >= 1 && a2 <= d);
        vm.deal(address(attacker), d);
        bool ok;
        try attacker.go{value: d}(c, a, a2) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract Attacker {
    C c;
    uint256 a2;
    bool reentered;

    function go(C c_, uint256 a, uint256 a2_) external payable {
        c = c_;
        a2 = a2_;
        reentered = false;
        c.deposit{value: msg.value}();
        c.withdraw(a);
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            c.withdraw(a2);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test() public {
        bool ok;
        (ok, ) = address(c).call(abi.encodeWithSelector(c.deposit.selector));
        assert(!ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

