contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(uint256 amount) public {
        uint256 bal = address(this).balance;
        require(bal >= 1);

        // caller deposits 1 wei, so own balance is 1
        c.deposit{value: 1}();

        // request a withdrawal of 1 + amount (> own balance)
        bool ok;
        (ok, ) = address(c).call(
            abi.encodeWithSignature("withdraw(uint256)", amount + 1)
        );

        // P: the withdrawal must fail; M: it succeeds and the balance wraps
        assert(!ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

