contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 v) public payable {
        require(address(this).balance >= v);
        bool depReverted;
        try c.deposit{value: v}() { depReverted = false; } catch { depReverted = true; }
        bool wdReverted;
        try c.withdraw(v + 1) { wdReverted = false; } catch { wdReverted = true; }
        assert(!depReverted && wdReverted);
    }
    receive() external payable {}
}

